data <- matrix(1:20, nrow = 4, ncol = 5)
arr <- delarr::delarr_backend(
  nrow = 4,
  ncol = 5,
  pull = function(rows = NULL, cols = NULL) {
    if (is.null(rows)) rows <- seq_len(4)
    if (is.null(cols)) cols <- seq_len(5)
    data[rows, cols, drop = FALSE]
  }
)
res <- arr |>
  delarr::d_map(~ .x * 2) |>
  delarr::collect()
